// Exemple. Deux objets, dont un en double dans le même lot.
const env = (contrat, donnees, config) => ({ contrat: contrat, organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: 'exemple:banc:' + contrat.split('@')[0].slice(4), trace: { execution_parent: 'Exemple. banc', declencheur: 'banc', tentative: 0 }, config: config || {}, donnees: donnees });
return [1, 2, 1].map((i) => ({ json: env('lib-dedoublonner@1', { type: 'relance', objet_id: '00000000-0000-4000-8000-00000000010' + i, etape: 'palier-1' }) }));

// Bilan agrégé, sans donnée : par contrat, le nombre de sorties par statut. Un effet fait en simulation, ou un appel en erreur, compte en défaut.
const bilan = {};
let defauts = 0;
for (const { json: s } of $input.all()) {
  const c = typeof s.contrat === 'string' ? s.contrat : 'appel en erreur';
  bilan[c] = bilan[c] || {};
  const st = typeof s.statut === 'string' ? s.statut : 'erreur';
  bilan[c][st] = (bilan[c][st] || 0) + 1;
  if (!s.contrat || (s.simulation === true && Array.isArray(s.effets_faits) && s.effets_faits.length)) defauts++;
}
return [{ json: { bilan: bilan, defauts: defauts } }];

// Exemple. Deux décisions fictives.
const env = (contrat, donnees, config) => ({ contrat: contrat, organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: 'exemple:banc:' + contrat.split('@')[0].slice(4), trace: { execution_parent: 'Exemple. banc', declencheur: 'banc', tentative: 0 }, config: config || {}, donnees: donnees });
return [{ json: env('lib-journaliser@1', { entrees: [1, 2].map((i) => ({ evenement: 'decision', agent: 'ent-exemple-relance', objet_ref: 'Exemple. devis-000' + i, decision: 'Exemple. relance ' + i, simulation: true })) }) }];

// Exemple. Trois pannes du même workflow en une minute : une seule alerte.
const env = (contrat, donnees, config) => ({ contrat: contrat, organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: 'exemple:banc:' + contrat.split('@')[0].slice(4), trace: { execution_parent: 'Exemple. banc', declencheur: 'banc', tentative: 0 }, config: config || {}, donnees: donnees });
return [0, 20, 40].map((s) => ({ json: env('lib-alerter@1', { categorie: 'workflow_en_panne', workflow: 'ent-exemple-relance', lien_execution: null, destinataire_role: 'benj', survenue_le: new Date(Date.UTC(2026, 10, 2, 12, 0, s)).toISOString() }) }));

// Exemple. Trois échecs de suite : le troisième coupe l'agent.
const env = (contrat, donnees, config) => ({ contrat: contrat, organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: 'exemple:banc:' + contrat.split('@')[0].slice(4), trace: { execution_parent: 'Exemple. banc', declencheur: 'banc', tentative: 0 }, config: config || {}, donnees: donnees });
return [1, 2, 3].map(() => ({ json: env('lib-disjoncteur@1', { agent: 'ent-exemple-relance', issue: 'echec' }, { seuil: 3 }) }));

// Exemple. Un parent muet depuis 27 h.
const env = (contrat, donnees, config) => ({ contrat: contrat, organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: 'exemple:banc:' + contrat.split('@')[0].slice(4), trace: { execution_parent: 'Exemple. banc', declencheur: 'banc', tentative: 0 }, config: config || {}, donnees: donnees });
return [{ json: env('lib-battement@1', { workflow: 'ent-exemple-controle', passe_le: '2026-11-02T11:00:00.000Z', operation: 'controler', battements: [{ workflow: 'ent-exemple-parent', dernier_le: '2026-11-01T08:00:00.000Z', alerte_levee_le: null }] }) }];
